st = json.load(open('adesivos.json'))
st['deck'] = [s for s in st['deck'] if not s['id'].startswith('forma')]
for sid, (cor, poly, furos) in F.items():
    poly = [(min(XMAX, max(XMIN, x)), y) for x, y in poly]
    xs, ys = [p[0] for p in poly], [p[1] for p in poly]
    X0, X1, Y0, Y1 = min(xs) - 0.3, max(xs) + 0.3, min(ys) - 0.3, max(ys) + 0.3
    W, H = int((X1 - X0) * S * 4), int((Y1 - Y0) * S * 4)
    def P(x, y): return ((x - X0) * S * 4, (Y1 - y) * S * 4)
    a = Image.new('L', (W, H), 0); d = ImageDraw.Draw(a)
    d.polygon([P(x, y) for x, y in poly], fill=255)
    for cx, cy, rx, ry, ang in furos:
        e = Image.new('L', (W, H), 0); de = ImageDraw.Draw(e)
        px, py = P(cx, cy)
        de.ellipse([px - rx * S * 4, py - ry * S * 4, px + rx * S * 4, py + ry * S * 4], fill=255)
        e = e.rotate(ang, center=(px, py))
        a = Image.fromarray((np.asarray(a).astype(int) * (255 - np.asarray(e).astype(int)) // 255).astype(np.uint8))
    a = a.filter(ImageFilter.GaussianBlur(3)).resize((W // 4, H // 4), Image.LANCZOS)
    # cor: o tom da foto, clareado, com um leve degradê (o arco-íris de verdade vem do shader)
    g = np.linspace(0.92, 1.06, a.height)[:, None, None]
    rgb = np.clip(np.array(cor, np.float32)[None, None] * g * np.ones((a.height, a.width, 1)), 0, 255).astype(np.uint8)
    Image.fromarray(np.dstack([rgb, np.asarray(a)]), 'RGBA').save('arte/forma_%s.png' % sid)
    st['deck'].append({'id': 'forma_' + sid, 'fonte': 'forma', 'brilho': 'holo', 'desc': 'recorte holográfico liso (contorno à mão)',
                       'modelo_rect': [round(X0, 2), round(Y0, 2), round(X1, 2), round(Y1, 2)]})
json.dump(st, open('adesivos.json', 'w'), indent=1, ensure_ascii=False)
print(len(F), 'formas;', sum(1 for s in st['deck'] if s['id'].startswith('forma')), 'no apoio')
